<?php
// End-to-end coverage of every editable content field. Use a fresh isolated database on port 8097.
$base='http://127.0.0.1:8097';$cookie=tempnam(sys_get_temp_dir(),'parthvi-manager-');$passed=0;
function req($path,$data=null){global $base,$cookie;$c=curl_init($base.$path);curl_setopt_array($c,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_HEADER=>true,CURLOPT_COOKIEJAR=>$cookie,CURLOPT_COOKIEFILE=>$cookie]);if($data!==null){curl_setopt($c,CURLOPT_POST,true);curl_setopt($c,CURLOPT_POSTFIELDS,$data);}$raw=curl_exec($c);if($raw===false)throw new Exception(curl_error($c));$n=curl_getinfo($c,CURLINFO_HEADER_SIZE);$code=curl_getinfo($c,CURLINFO_RESPONSE_CODE);curl_close($c);return ['status'=>$code,'body'=>substr($raw,$n),'headers'=>substr($raw,0,$n)];}
function ok($value,$message){global $passed;if(!$value)throw new Exception('FAIL: '.$message);$passed++;echo "PASS: $message\n";}
function editor($html){$doc=new DOMDocument();@$doc->loadHTML($html);$xp=new DOMXPath($doc);$out=[];foreach($xp->query('//form[contains(@class,"editor-form")]//input | //form[contains(@class,"editor-form")]//textarea') as $f){$name=$f->getAttribute('name');$type=$f->getAttribute('type');if(!$name||in_array($type,['file','submit'])||($type==='checkbox'&&!$f->hasAttribute('checked')))continue;$out[$name]=$f->nodeName==='textarea'?$f->textContent:$f->getAttribute('value');}return $out;}
function csrf($html){preg_match('/name="csrf" value="([a-f0-9]+)"/',$html,$m);return $m[1]??'';}
function page_form($slug){return editor(req('/admin/index.php?section=pages&slug='.$slug)['body']);}
function item_id($html,$name){$d=new DOMDocument();@$d->loadHTML($html);$xp=new DOMXPath($d);foreach($xp->query('//tr') as $r)if(str_contains($r->textContent,$name)){foreach($xp->query('.//a[contains(@href,"edit=")]',$r) as $a){parse_str(parse_url($a->getAttribute('href'),PHP_URL_QUERY),$q);return $q['edit'];}}return null;}
try {
 $r=req('/admin/login.php');$r=req('/admin/login.php',['csrf'=>csrf($r['body']),'email'=>'admin@gmail.com','password'=>getenv('PARTHVI_TEST_PASSWORD')?:'123456']);ok($r['status']===302,'Sign in to isolated content audit');
 $f=page_form('index');$f['copy_hero_main_image']=new CURLFile(dirname(__DIR__).'/assets/images/catalogue/cumin-seeds.webp','image/webp','ingredient.webp');$r=req('/admin/index.php?section=pages&slug=index',$f);ok($r['status']===302,'WebP image upload works on this server');ok((bool)preg_match('~class="hero-main-product"[^>]+src="assets/uploads/[a-f0-9]+\.webp"~',req('/')['body']),'Uploaded WebP is used in hero');
 $f=editor(req('/admin/index.php?section=certificates&edit=new')['body']);$f=array_merge($f,['title'=>'Dynamic audit certificate','label'=>'QA','description'=>'No-preview fallback check','file'=>new CURLFile(dirname(__DIR__).'/assets/documents/parthvi-exim-iec-certificate.pdf','application/pdf','qa.pdf')]);ok(req('/admin/index.php?section=certificates&edit=new',$f)['status']===302,'Create certificate without preview to cover fallback labels');
 $schema=json_decode(file_get_contents(dirname(__DIR__).'/includes/content-schema.json'),true);$expected=[];
 foreach($schema as $slug=>$fields){$f=page_form($slug);foreach($fields as $key=>$field){$type=$field['type']??'text';if($type==='toggle'){$f['copy_'.$key]='1';continue;}if(!in_array($type,['text','textarea','link']))continue;$marker='DYN_'.str_replace('-','_',$slug).'_'.$key;$f['copy_'.$key]=$type==='link'?'https://example.com/'.$marker:$marker;$expected[$slug.'.'.$key]=$marker;}$r=req('/admin/index.php?section=pages&slug='.$slug,$f);ok($r['status']===302,'Save all content controls: '.$slug);}
 $html='';foreach(['/','/about','/products','/contact','/certificates','/privacy-policy','/terms-and-conditions','/products/white-onion-flakes','/products/unavailable-product','/not-a-real-page','/categories/dehydrated-white-onion'] as $path)$html.=req($path)['body'];
 $r=req('/contact');$post=['csrf'=>csrf($r['body']),'name'=>'Dynamic QA','email'=>'dynamic@example.com','phone'=>'','country'=>'India','company'=>'QA','product'=>'general','quantity'=>'Isolated content check','website'=>''];$r=req('/contact',$post);ok($r['status']===303,'Submit inquiry with managed text');$html.=req('/contact')['body'];
 $missing=[];foreach($expected as $key=>$marker){if(!str_contains($html,$marker))$missing[]=$key;else $passed++;}
 echo 'Verified '.(count($expected)-count($missing)).' of '.count($expected)." content controls in public responses.\n";
 echo 'MISSING_CONTROLS '.json_encode($missing)."\n";ok(!$missing,'Every text/link control reaches the public website');
 $f=page_form('about');$f['copy_mission_label']='Same heading';$f['copy_vision_label']='Same heading';$f['copy_purpose_label']='Same heading';req('/admin/index.php?section=pages&slug=about',$f);ok(substr_count(req('/about')['body'],'<h3>Same heading</h3>')===3,'Matching principle titles retain all three cards');
 $f=page_form('index');unset($f['copy_show_hero']);req('/admin/index.php?section=pages&slug=index',$f);$home=req('/')['body'];ok(!str_contains($home,'class="fresh-hero"')&&str_contains($home,'<h1 class="visually-hidden">'),'Hiding hero preserves the page heading');
 echo "\n$passed dynamic content checks passed.\n";
}finally{unlink($cookie);}
